<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { MessageCircle, Send, Search, CircleHelp } from "lucide-vue-next";
import SiteHeader from "../components/SiteHeader.vue";
import SiteFooter from "../components/SiteFooter.vue";

interface Message { id: string; text: string; sent: boolean; time: string }
interface Conversation { seller: string; last: string; messages: Message[] }
const route = useRoute();
const conversations = ref<Conversation[]>(JSON.parse(localStorage.getItem("bx-chats") ?? "null") as Conversation[] ?? [
  { seller: "TechStore Official", last: "Thanks for reaching out. How can we help?", messages: [{ id: "m1", text: "Hi, is this item available?", sent: true, time: "10:20 AM" }, { id: "m2", text: "Thanks for reaching out. How can we help?", sent: false, time: "10:23 AM" }] },
  { seller: "StyleHub", last: "We can help with sizing details.", messages: [{ id: "m3", text: "We can help with sizing details.", sent: false, time: "Yesterday" }] },
  { seller: "GroceryMart", last: "Your question was received.", messages: [{ id: "m4", text: "Your question was received.", sent: false, time: "Mon" }] },
]);
const selectedSeller = ref(String(route.params.seller ?? conversations.value[0]?.seller ?? ""));
const message = ref("");
const search = ref("");
const current = computed(() => conversations.value.find((item) => item.seller === selectedSeller.value));
const filtered = computed(() => conversations.value.filter((item) => item.seller.toLowerCase().includes(search.value.toLowerCase())));
watch(() => route.params.seller, (value) => { if (value && conversations.value.some((item) => item.seller === value)) selectedSeller.value = String(value); });
function send() { const text = message.value.trim(); if (!text || !current.value) return; current.value.messages.push({ id: `m-${Date.now()}`, text, sent: true, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }); current.value.last = text; message.value = ""; localStorage.setItem("bx-chats", JSON.stringify(conversations.value)); }
</script>

<template><div class="page-shell"><SiteHeader /><main class="container content-page"><div class="breadcrumb"><RouterLink to="/">Home</RouterLink><span>/</span><span>Buyer–Seller chat</span></div><div class="chat-title"><span class="eyebrow">MESSAGES</span><h1>Buyer–Seller chat</h1><p>Ask stores about products and orders before you buy.</p></div><section class="chat-window"><aside class="chat-list"><h2>Conversations</h2><label><Search /><input v-model="search" aria-label="Search conversations" placeholder="Search stores" /></label><button v-for="item in filtered" :key="item.seller" :class="{ selected: selectedSeller === item.seller }" @click="selectedSeller = item.seller"><span class="store-avatar">{{ item.seller.charAt(0) }}</span><span><b>{{ item.seller }}</b><small>{{ item.last }}</small></span></button><p v-if="!filtered.length" class="chat-empty-list">No conversations found.</p></aside><section v-if="current" class="chat-body"><header><span class="store-avatar">{{ current.seller.charAt(0) }}</span><div><b>{{ current.seller }}</b><small>Marketplace seller</small></div></header><div class="message-history"><p class="chat-safety"><CircleHelp /> Keep payment on BazaarX for purchase protection.</p><article v-for="item in current.messages" :key="item.id" :class="{ mine: item.sent }"><span>{{ item.text }}</span><small>{{ item.time }}</small></article></div><form @submit.prevent="send"><input v-model="message" aria-label="Type your message" placeholder="Type a message..." /><button :disabled="!message.trim()" aria-label="Send message"><Send /></button></form></section><section v-else class="chat-no-selection"><MessageCircle /><b>Choose a conversation</b><p>Select a seller to read and send messages.</p></section></section></main><SiteFooter /></div></template>

